// Preview-only evaluator for the exact redirects generated by build-legacy.mjs.
// The deployed site uses vercel.json or the generated Apache configuration.
export function resolveRedirect(config,url){
 for(const rule of config.redirects||[]){
  if(rule.source!==url.pathname)continue;const captures={};let matches=true;
  for(const test of rule.has||[]){const value=test.type==='query'?url.searchParams.get(test.key):test.type==='host'?url.hostname:null;if(value===null){matches=false;break}const match=new RegExp('^(?:'+test.value+')$').exec(value);if(!match){matches=false;break}Object.assign(captures,match.groups||{});}
  if(!matches)continue;
  const target=new URL(rule.destination.replace(/:([A-Za-z][A-Za-z0-9_]*)/g,(_,key)=>encodeURIComponent(captures[key]||'')),url.origin);
  for(const [key,value]of url.searchParams)if(!target.searchParams.has(key))target.searchParams.append(key,value);
  return {status:rule.statusCode||(rule.permanent?308:307),location:target.pathname+target.search};
 }
 return null;
}
